import React from "react";
import styled from "styled-components";
import ellieProfile from "../../images/ellieProfile.jpg";

interface ProfileHeaderProps {
  type: "customer" | "business";
  name: string;
  stat1: number;
  stat2: number;
  stat3: number;
}

const Container = styled.div`
  width: 1200px;
  background: #ffffff;
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
`;

const HeaderBanner = styled.div`
  height: 140px;
  background-color: #76949F;
  width: 100%;
`;

const Content = styled.div`
  padding: 24px 32px;
  display: flex;
  flex-direction: column;
`;

const InfoRow = styled.div`
  display: flex;
  align-items: center;
  gap: 16px;
`;

const ProfileImage = styled.img`
  width: 90px;
  height: 90px;
  border-radius: 50%;
  border: 4px solid #fff;
  margin-top: -45px;
  object-fit: cover;
`;

const Name = styled.div`
  font-size: 22px;
  font-weight: 700;
  color: #1a1a1a;
`;

const StatsRow = styled.div`
  display: flex;
  gap: 80px;
  margin-top: 24px;
`;

const StatBlock = styled.div`
  display: flex;
  flex-direction: column;
  text-align: center;
`;

const StatNumber = styled.div`
  font-size: 22px;
  font-weight: 700;
  color: #1a1a1a;
`;

const StatLabel = styled.div`
  font-size: 13px;
  color: #6d6d6d;
  margin-top: 2px;
`;

const ProfileHeader: React.FC<ProfileHeaderProps> = ({
  type,
  name,
  stat1,
  stat2,
  stat3,
}) => {
  return (
    <Container>
      <HeaderBanner />

      <Content>
        <InfoRow>
          <ProfileImage src={ellieProfile} alt="Profile" />
          <Name>{name}</Name>
        </InfoRow>

        {/* Customer stats */}
        {type === "customer" && (
          <StatsRow>
            <StatBlock>
              <StatNumber>{stat1}</StatNumber>
              <StatLabel>Bookings</StatLabel>
            </StatBlock>
            <StatBlock>
              <StatNumber>{stat2}</StatNumber>
              <StatLabel>Visited</StatLabel>
            </StatBlock>
            <StatBlock>
              <StatNumber>{stat3}</StatNumber>
              <StatLabel>Active Loyalty Programs</StatLabel>
            </StatBlock>
          </StatsRow>
        )}

        {/* Business stats */}
        {type === "business" && (
          <StatsRow>
            <StatBlock>
              <StatNumber>{stat1}</StatNumber>
              <StatLabel>Avg Rating</StatLabel>
            </StatBlock>
            <StatBlock>
              <StatNumber>{stat2}</StatNumber>
              <StatLabel>Total Clients</StatLabel>
            </StatBlock>
            <StatBlock>
              <StatNumber>{stat3}</StatNumber>
              <StatLabel>Staff Members</StatLabel>
            </StatBlock>
          </StatsRow>
        )}
      </Content>
    </Container>
  );
};

export default ProfileHeader;
